//                             In The Name Of Allah                                           
//                             	Mohammad Hosseini
#include <bits/stdc++.h>
#define	ss second
#define ff first
#define use_fast ios::sync_with_stdio(false), cin.tie(0), cout.tie(0)
#define ret(n) return cout << n, 0
#define se(n) cout << setprecision(n) << fixed
#define pb push_back
#define int long long
#define ld long double
#pragma GCC optimize("Ofast,no-stack-protector,unroll-loops")
#pragma GCC optimize("no-stack-protector,fast-math")
//#pragma GCC target("sse,sse2,sse3,ssse3,sse4,popcnt,abm,mmx,avx,tune=native")
using namespace std; 

const int N = 1e6 + 100, OO = 1e9 + 7, M = 1e9 + 7, P = 6151, T = 2e3, SQ = 280, lg = 64, lg2 = 34;
typedef pair <int, int> pii;
int n, d;
vector <int> v;

struct node {
	int dp[lg2][lg2], cnt[lg2][lg2];
	bool mark[lg2], tark[lg2];
	void mrg(node &nd) {
		for(int i = 0; i <= d; i++) {
			for(int j = 0; j <= d; j++) {
				cnt[i][j] = 0;
				for(int k = 0; k <= d; k++) 
					cnt[i][j] = (cnt[i][j] + dp[k][j] * nd.dp[i][k]) % M;
			}
		}
		for(int i = 0; i < d; i++) {
			if(mark[i] == true && nd.mark[i] == false) {
				for(int j = 0; j <= d; j++)
					cnt[i][j] = dp[i][j];
			}
			if(mark[i] == false && nd.mark[i] == true) { 
				for(int j = 0; j <= d; j++)
					cnt[j][i] = nd.dp[j][i];
			}
			mark[i] |= nd.mark[i];
		}
		for(int i = 0; i <= d; i++)
			for(int j = 0; j <= d; j++)
				dp[i][j] = cnt[i][j];
	}
	void clean() {
		for(int i = 0; i <= d; i++)
			for(int j = 0; j <= d; j++)
				dp[i][j] = cnt[i][j] = 0;
	}
	void shift(int x) {
		for(int i = 0; i <= d; i++)
			for(int j = 0; j <= d; j++)
				cnt[i][j] = 0;
		for(int i = 0; i < d; i++) {
			for(int j = 0; j < d; j++) 
				cnt[(i + x) % d][(j + x) % d] = dp[i][j];	
			cnt[(i + x) % d][d] = dp[i][d];
		}
		for(int i = 0; i < d; i++)
			cnt[d][(i + x) % d] = dp[d][i];
		cnt[d][d] = dp[d][d];
		for(int i = 0; i <= d; i++)
			for(int j = 0; j <= d; j++)
				dp[i][j] = cnt[i][j];
		for(int i = 0; i < d; i++)
			tark[i] = mark[(i + x) % d];
		for(int i = 0; i < d; i++)
			mark[i] = tark[i];
	}
} md[lg + 5], hp[lg + 5], ht;

node get(int x) {
	int h = x, pw = 1, t = -1;
	while(h >= d)
		h /= d, pw *= d, t++;
	x %= pw;
	if(t == -1) 
		return hp[h];
	node ans = md[t];
	ht = md[t];
	for(int i = 1; i < h; i++) {
		ht.shift(1);
		ans.mrg(ht);
	}
	ht = get(x);
	ht.shift(h);	
	ans.mrg(ht);
	return ans;
}

int32_t main() {
    use_fast;
	cin >> n >> d;
	n--;
	int m = n;
	while(n) {
		v.pb(n % d);
		n /= d;
	}
	hp[0].dp[d][d] = 2;
	hp[0].dp[d][0] = -1;
	hp[0].dp[0][d] = 1;
	hp[0].mark[0] = true;
	md[0] = hp[0];
	for(int i = 1; i < d; i++) {
		hp[i].dp[d][d] = 2;
		hp[i].dp[d][i] = -1;
		hp[i].dp[i][d] = 1;
		hp[i].mark[i] = true;
		md[0].mrg(hp[i]);
		hp[i] = md[0];
	}
	for(int i = 1; i <= (int)v.size(); i++) {
		md[i] = md[i - 1];
		ht = md[i - 1];
		for(int j = 1; j < d; j++) {
			ht.shift(1);
			md[i].mrg(ht);
		}
	}
	node ans = get(m);
	cout << ans.dp[d][d] << endl;
	return 0;
}
